(async()=>{const sleep=ms=>new Promise(r=>setTimeout(r,ms));await sleep(1500);const p=document.querySelector('.map-page'),img=document.querySelector('.map-plane img'),list=document.querySelector('.map-fallback-list');
const ink=c=>{try{const x=c&&c.getContext('2d');return !!x&&x.getImageData(0,0,c.width,c.height).data.some(v=>v!==0)}catch(e){return false}};
const stale={trail:ink(document.querySelector('.map-trail')),radar:ink(document.querySelector('.map-radar')),terrain:ink(document.querySelector('.map-terrain'))};
const beads=document.querySelectorAll('.map-pin').length,card=document.querySelectorAll('.map-card').length,buttons=[...document.querySelectorAll('main button')].filter(b=>!b.closest('[hidden]')).length;
return JSON.stringify({engine:p.dataset.engine,picture:img?[img.naturalWidth,img.complete]:null,list:list?list.querySelectorAll('li').length:0,switch:document.querySelectorAll('.map-mode').length,terrain:document.querySelector('.map-stage').dataset.terrain??null,
srList:document.querySelectorAll('.sr-only li').length,beads,card,mainButtons:buttons,stale,ok:p.dataset.engine==='off'&&!!list&&list.querySelectorAll('li').length===9&&document.querySelectorAll('.map-mode').length===0&&beads===0&&card===0&&!stale.trail&&!stale.radar&&!stale.terrain&&!!img&&img.naturalWidth>0})})()

